import React from 'react'

function Footer() {
    return (
        <div className='container'>
            <div className='row'>
                <div className='col'>
                    <img src='Media/images/logo.svg' alt='logo' style={{ width: "50%" }} />
                </div>
                <div className='col'>
                    <p>Company</p>
                </div>
                <div className='col'></div>
                <div className='col'></div>
            </div>
        </div>
    );
}

export default Footer;
